#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=6
ENV_FILE=".env.local"
ROOT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
cd "$ROOT_DIR"

banner "Trick-or-treat → Supabase + Vercel"

# ── 1. Create Supabase project ────────────────────────────────────────────
stage "Create Supabase project"
say "Det gamle prosjektet er borte — vi trenger et nytt."
open_url "https://supabase.com/dashboard"
step "Logg inn (eller lag konto) hvis du ikke allerede er inne."
step "Klikk New project."
step "Velg org, gi prosjektet et navn (f.eks. trick-or-treat-app)."
step "Sett et database-passord og lagre det et trygt sted (trengs sjelden senere)."
step "Velg region nær deg (f.eks. Frankfurt / eu-central-1) og klikk Create new project."
step "Vent til prosjektet er ferdig provisionert (grønn status)."
pause "Trykk Enter når prosjektet er klart."

# ── 2. API keys → .env.local ──────────────────────────────────────────────
stage "API keys → .env.local"
say "Vi henter Project URL og anon-nøkkelen til lokal kjøring og Vercel."
open_url "https://supabase.com/dashboard/project/_/settings/api"
step "Åpne Settings → API for det nye prosjektet (bytt prosjekt i sidebar hvis '_' er feil)."
step "Kopier Project URL (ser ut som https://xxxx.supabase.co)."
ask NEXT_PUBLIC_SUPABASE_URL "Lim inn Project URL (https://xxxx.supabase.co — uten /rest/v1):"
step "Under Project API keys, kopier anon public-nøkkelen (ikke service_role)."
ask_secret NEXT_PUBLIC_SUPABASE_ANON_KEY "Lim inn anon public-nøkkelen:"
if [[ -z "$NEXT_PUBLIC_SUPABASE_URL" || -z "$NEXT_PUBLIC_SUPABASE_ANON_KEY" ]]; then
  warn "URL og anon-nøkkel må begge fylles ut. Avbryter."
  exit 1
fi
# Normalize: strip trailing slash and accidental /rest/v1 path
NEXT_PUBLIC_SUPABASE_URL="${NEXT_PUBLIC_SUPABASE_URL%/}"
NEXT_PUBLIC_SUPABASE_URL="${NEXT_PUBLIC_SUPABASE_URL%/rest/v1}"
if [[ ! "$NEXT_PUBLIC_SUPABASE_URL" =~ ^https://[a-z0-9]+\.supabase\.co$ ]]; then
  warn "URL skal være https://<ref>.supabase.co (ingen path). Fikk: $NEXT_PUBLIC_SUPABASE_URL"
  exit 1
fi
if [[ ! "$NEXT_PUBLIC_SUPABASE_ANON_KEY" =~ ^eyJ ]]; then
  warn "anon-nøkkelen skal starte med eyJ … sjekk at du ikke limte inn URL som nøkkel."
  exit 1
fi
write_env NEXT_PUBLIC_SUPABASE_URL "$NEXT_PUBLIC_SUPABASE_URL"
write_env NEXT_PUBLIC_SUPABASE_ANON_KEY "$NEXT_PUBLIC_SUPABASE_ANON_KEY"

# Derive project ref for later deep-links
PROJECT_REF=""
if [[ "$NEXT_PUBLIC_SUPABASE_URL" =~ https://([a-z0-9]+)\.supabase\.co ]]; then
  PROJECT_REF="${BASH_REMATCH[1]}"
fi

# ── 3. Run SQL migrations ─────────────────────────────────────────────────
stage "Kjør database-migrasjoner"
say "To SQL-filer skal kjøres i SQL Editor (i rekkefølge)."
if [[ -n "$PROJECT_REF" ]]; then
  open_url "https://supabase.com/dashboard/project/${PROJECT_REF}/sql/new"
else
  open_url "https://supabase.com/dashboard/project/_/sql/new"
fi
step "SQL Editor → New query er åpnet."
if command -v pbcopy >/dev/null 2>&1; then
  pbcopy < "$ROOT_DIR/supabase/migrations/001_initial_schema.sql"
  note "001_initial_schema.sql er kopiert til utklippstavlen."
else
  note "Åpne filen: supabase/migrations/001_initial_schema.sql og kopier ALT."
fi
step "Lim inn i editoren og klikk Run (Cmd+Enter)."
pause "Trykk Enter når 001 er kjørt uten feil."
if command -v pbcopy >/dev/null 2>&1; then
  pbcopy < "$ROOT_DIR/supabase/migrations/004_add_avatar_to_users.sql"
  note "004_add_avatar_to_users.sql er kopiert til utklippstavlen."
else
  note "Åpne filen: supabase/migrations/004_add_avatar_to_users.sql og kopier ALT."
fi
step "Ny query → lim inn 004 → Run."
pause "Trykk Enter når 004 er kjørt."
step "Valgfritt: Table Editor skal vise groups (2 rader), users, checkins, photos."

# ── 4. Storage bucket ─────────────────────────────────────────────────────
stage "Storage-bucket candy-photos"
say "Appen laster opp godtebilder til en public bucket."
if [[ -n "$PROJECT_REF" ]]; then
  open_url "https://supabase.com/dashboard/project/${PROJECT_REF}/storage/buckets"
else
  open_url "https://supabase.com/dashboard/project/_/storage/buckets"
fi
step "Klikk New bucket."
step "Name: candy-photos"
step "Sett Public bucket til ON (så bilder kan hentes via URL)."
step "Create bucket."
step "Åpne bucketen → Policies (eller Configuration → Policies)."
step "Legg til policy for SELECT (read) for roles anon + authenticated, expression: true."
step "Legg til policy for INSERT (upload) for roles authenticated (og evt. anon), expression: true."
note "Hvis UI tilbyr 'Allow public read' / quick policies, bruk dem for read + upload."
pause "Trykk Enter når bucket + policies er på plass."

# ── 5. Anonymous auth ─────────────────────────────────────────────────────
stage "Skru på Anonymous Auth"
say "Login-siden bruker signInAnonymously() — uten denne feiler signup."
if [[ -n "$PROJECT_REF" ]]; then
  open_url "https://supabase.com/dashboard/project/${PROJECT_REF}/auth/providers"
else
  open_url "https://supabase.com/dashboard/project/_/auth/providers"
fi
step "Finn Anonymous under Auth Providers."
step "Enable / toggle den på, og lagre."
pause "Trykk Enter når Anonymous er enabled."

# ── 6. Deploy til Vercel ──────────────────────────────────────────────────
stage "Deploy til Vercel"
say "Setter env-variabler og deployer Next.js-appen."
if ! command -v vercel >/dev/null 2>&1; then
  warn "vercel CLI mangler. Installer med: npm i -g vercel"
  SKIPPED+=("Vercel deploy (kjør: vercel login && vercel --prod)")
else
  if ! vercel whoami >/dev/null 2>&1; then
    say "Du må logge inn i Vercel CLI."
    vercel login
  fi
  note "Linket/oppretter prosjekt (ikke-interaktivt der det går)…"
  # Link without overwriting if already linked; create project named trick-or-treat-app
  if [[ ! -f .vercel/project.json ]]; then
    vercel link --yes --project trick-or-treat-app || vercel link --yes
  fi
  _upsert_vercel_env() {
    local name="$1" value="$2" env="$3"
    # NEXT_PUBLIC_* must be type=config (not secret) or Vercel CLI refuses / prompts wrongly
    vercel env add "$name" "$env" --type config --value "$value" --yes --force >/dev/null
    printf '  %s✓ vercel env%s %s → %s\n' "$GREEN" "$RESET" "$name" "$env"
  }
  for _env in production preview development; do
    _upsert_vercel_env NEXT_PUBLIC_SUPABASE_URL "$NEXT_PUBLIC_SUPABASE_URL" "$_env"
    _upsert_vercel_env NEXT_PUBLIC_SUPABASE_ANON_KEY "$NEXT_PUBLIC_SUPABASE_ANON_KEY" "$_env"
  done
  say "Starter production deploy…"
  vercel --prod --yes
  note "Når deploy er ferdig, åpne Production URL fra output over."
fi

# ──────────────────────────────────────────────────────────────────────────

finish
say "Neste steg: åpne Production URL, trykk Get Started, og sjekk at login + groups fungerer."
say "Si ifra til agenten når wizarden er ferdig, så kan den verifisere API/deploy."
